from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel


class SendTaskFailureInput(SdkBaseModel):
    task_token: str = Field(alias="taskToken")
    """The token that represents this task. Task tokens are generated by Step Functions when tasks are assigned to a
    worker, or in the context object when a workflow enters a task state. See GetActivityTaskOutput$taskToken."""

    error: Optional[str] = UNSET
    """The error code of the failure."""

    cause: Optional[str] = UNSET
    """A more detailed explanation of the cause of the failure."""


class SendTaskFailureInputDict(TypedDict):
    task_token: str
    error: NotRequired[str]
    cause: NotRequired[str]
